// Noir-Schwarzweiss: harte Kontrast-Kurve, Korn, kraeftige Vignette —
// der Bass drueckt den Kontrast zusaetzlich.
float hash(vec2 p) { return fract(sin(dot(p, vec2(12.9898, 78.233))) * 43758.5453); }
vec4 farbe(vec2 uv, vec4 src)
{
    float grau = dot(src.rgb, vec3(0.299, 0.587, 0.114));
    float kontrast = 1.6 + 0.8 * bass;
    grau = clamp((grau - 0.5) * kontrast + 0.48, 0.0, 1.0);
    grau = smoothstep(0.05, 0.95, grau);
    float korn = hash(uv * uResolution * 0.5 + floor(uTime * 24.0));
    grau += (korn - 0.5) * 0.06;
    vec2 d = uv - 0.5;
    grau *= 1.0 - 0.6 * dot(d, d) * 2.0;
    return vec4(vec3(clamp(grau, 0.0, 1.0)), 1.0);
}
